"use strict";

// The same defect with the computed key on a METHOD rather than a field --
// the form where BOTH the value and the body are deferred and only the key
// runs at class-definition time. An analyzer whose class walk stops at
// function-like nodes (a `MethodDeclaration` is one) never sees this key
// at all unless it asks about the key BEFORE that stop.
function dangerousOp(input) {
  return require("./danger").explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Mode {
    // The BODY never runs -- nothing calls this method. The KEY runs while
    // the class is being defined, and throws.
    [bail()]() {
      return "unreachable body";
    }
  }
}

module.exports = safeOp;
